<body> <?php $TitleMod ="Roles";$Table = "GrupoUsuarios";$TableJoin = "Permisos";$Key = "IDGrupoUsuarios";$MOD = "permbiblio";$TABsel = 2;$array_permiso = array("1"=>"acceso denegado","2"=>"solo lectura","3"=>"lectura - escritura");?> <?php 		$permisos = get_permiso($ID_Usuario,$m,$Table);if($permisos[0] >= 2){		switch (nvl($action)) {			case "add" :				print_form("","insert","Nuevo Registro $TitleMod","Agregar Registro");			break;			case "list" :				if(isset($_GET['listar'])) 						$listar = $_GET['listar'];						$sql = make_qry_string($HTTP_GET_VARS);					if(!empty($_GET['QryString'])) 						$sql = make_qry_string($HTTP_GET_VARS);					list_r($sql,$listar);			break;			case "insert" :				$frm= vars_LOG($HTTP_POST_VARS);				$id = insert($frm);				$Table = "Permisos";				$Key = "IDPermisos";				$frm[IDGrupoUsuarios]=$id;				insert($frm);				$Table = "GrupoUsuarios";				$Key = "IDGrupoUsuarios";				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;			case "edit":				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break ;			case "update" :				$frm= vars_LOG($HTTP_POST_VARS);				load_permisos($frm);				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;			case "update_perm" :				$frm= vars_LOG($HTTP_POST_VARS);				update_permisos($frm);				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;			case "delperm" :				db_query("DELETE FROM Permisos WHERE IDPermisos = '$id_perm'");				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;			default : 				print_form($id,"update","Actualizar $TitleMod","Realizar Cambios");			break;				} // End switchfunction load_permisos($frm){	Global $Nombre_Usuario,$ID;	$flag = 1;	$IDPermiso = get_maxID("Permisos","IDPermisos");	$now=fecha()." ".hora();	$sql_verif_perm ="		SELECT IDGrupoUsuarios, IDModuloSite,IDSeccionSite,Permiso 		FROM Permisos 		WHERE IDGrupoUsuarios = '$frm[ID]'		AND IDModuloSite = '$frm[IDModuloSite]'		AND IDSeccionSite = '$frm[IDSeccionSite]'		";	$qry_verif_perm = db_query($sql_verif_perm);	if(db_num_rows($qry_verif_perm)){		window_alert("Ya existe un permiso con esas caracteristicas para este Grupo ");		return 0;	}	$sql_perm = "		INSERT INTO Permisos (IDPermisos, IDGrupoUsuarios, IDModuloSite, IDSeccionSite, SeccionSite_name,Permiso,  UsuarioTrCr,  FechaTrCr) 					  VALUES('$IDPermiso','$frm[ID]','$frm[IDModuloSite]','$frm[IDSeccionSite]','$frm[SeccionSite_name]','$frm[Permiso]','$Nombre_Usuario','$now')	";	db_query($sql_perm);	window_alert("Registro Agregado correctamente ");}function update_permisos($frm){	Global $Nombre_Usuario;	$IDPermiso = get_maxID("Permisos","IDPermisos");	$now=fecha()." ".hora();	$sql_update_perm = "	UPDATE Permisos 	SET	IDModuloSite = '$frm[IDModuloSite]',	SeccionSite_name = '$frm[SeccionSite_name]',	IDSeccionSite = '$frm[IDSeccionSite]',	Permiso= '$frm[Permiso]',	UsuarioTrEd = '$Nombre_Usuario',	FechaTrEd = '$now'	WHERE IDPermisos = $frm[id_perm]	";	$qry_update_perm = db_query($sql_update_perm);	window_alert("Registro Actualizado correctamente ");}/*******************************************************************************************		funtcion Print_form*******************************************************************************************/function print_form($id="",$newmode,$title,$submit_caption) {	GLOBAL $TitleMod,$Table,$MOD,$Key,$dir_img, $folder_img_directorio,$imagedir,$strcript,$array_nivel,$TableJoin;	GLOBAL $verdir_w,$verdir_h,$options,$action,$array_permiso,$idnot;	$qid = db_query(" SELECT * FROM $Table WHERE $Key = '$idnot' ");	$r = db_fetch_object($qid);?><script>function editPerm( idpermiso, idmodulo, seccion, permiso, idseccion ) {	var f = document.frm;	f.action.value="update_perm";	f.id_perm.value=idpermiso;	f.IDSeccionSite.value=idseccion;	f.SeccionSite_name.value = seccion;	for(var i=0, n=f.IDModuloSite.options.length; i < n; i++) {		if (f.IDModuloSite.options[i].value == idmodulo) {			f.IDModuloSite.selectedIndex = i;			break;		}	}	f.Permiso.selectedIndex = permiso-1;}function validarModulo() {	var f = document.frm;	var pgo = f.IDModuloSite.options[f.IDModuloSite.selectedIndex].value;	if((pgo in tables) && f.SeccionSite_name.value == 'Todos'){		alert('Esta restriccion no aplica');		return false;	}	if(f.Nombre.value == ""){		alert('El campo Nombre es obligarotio');		f.Nombre.focus();		return false;	}	if(f.IDModuloSite.value == -1){		alert('Seleccione un Modulo');		f.IDModuloSite.focus();		return false;	}}function popPermItem() {    url = "directorio/popup_categorias.php?id=<?php echo $id?>";    url     += "&id_div=IDSeccionSite";    url     += "&id_campo_name=SeccionSite_name";    window.open(url,'categorias','toolbar=no,directories=no,location=no,status=no,menubar=no,resizable=yes,scrollbars=yes,width=500,height=400');}// Callback funcion para retorno de selectorfunction setPermItem( key, val ) {	var f = document.frm;	if (val != '') {		f.IDSeccionSite.value = key;		f.SeccionSite_name.value = val;	} else {		f.IDSeccionSite.value = '-1';		f.SeccionSite_name.value = 'Todos';	}}function delPerm(id,idp){	var fRet;		fRet = confirm('Esta seguro de eliminar ester permiso?');	if(fRet)		window.location.href = "?mod=<?php echo $MOD?>&action=delperm&id=" + id + "&id_perm=" + idp}</script><table cellspacing='0' cellpadding='2' border='0' width='454' bgcolor='#FFFFFF'>		<tr>			<td class=nav width=76%>&nbsp;&nbsp;&nbsp;&nbsp;<img src=images/usrperm.png border=0> <a href="./?mod=ListModulos&idnot=<?php echo $idnot?>">Administrar Roles de M&oacute;dulos</a></td>		</tr></table><?php 	if($newmode=="update")	include("directorio/menugrupo.php");?>	<form name="frm" action="" method="post" enctype="multipart/form-data" <?php if($newmode!="delete"){?>onsubmit=" return validarModulo(); return EvaluaReg(this,Check);"<?php }?>>		<table cellpadding=1 cellspacing=0 class=bordertable >	<tr>		<td class=maintitle bgcolor=#9daac6>&nbsp;<?php echo $TitleMod ?> </td>	</tr>	<tr>	<td>		<table width=443 border=0 cellspacing=1 cellpadding=1 class=texto>						<?php  $qry_perm = db_query("SELECT * FROM Permisos WHERE IDGrupoUsuarios = '$r->IDGrupoUsuarios' AND IDModuloSite = 3");			if(db_num_rows($qry_perm)){			?>						<tr>							<td colspan="2">				<table width=100% class=bordertable>					<tr  class="category">						<td align="center">Editar</td>						<td align="center">M&oacute;dulo</td>						<td align="center" colspan=2>&Iacute;tem</td>						<td align="center">Acceso</td>						<td align="center">Eliminar</td>					</tr>					<?php 					while($r_perm=db_fetch_object($qry_perm)){					?>						<tr  class="row1">						<td align="center" width=5><a href=# onClick="editPerm(<?php echo $r_perm->IDPermisos ?>,'<?php echo $r_perm->IDModuloSite ?>','<?php echo $r_perm->SeccionSite_name ?>',<?php echo $r_perm->Permiso?>,'<?php echo $r_perm->IDSeccionSite ?>');" title="editar este permiso"><img src='images/lock.gif' border='0'></a></td>						<td align="center"><?php  $Modulo = get_field("ModuloSite","NombreModulo","IDModuloSite",$r_perm->IDModuloSite); if($r_perm->IDModuloSite != -1) echo $Modulo; else echo "Todos";?></td>						<td align="center" colspan=2><?php echo $r_perm->SeccionSite_name ?></td>						<td align="center"><?php echo $array_permiso[$r_perm->Permiso]?></td>						<td align="center"><!--a href='<?php echo "?mod=$MOD&action=delperm&id=";echo $r->$Key; echo "&id_perm="; echo $r_perm->IDPermisos; ?>' title="eliminar este permiso"-->						<a href="javascript:delPerm('<?php echo $r->$Key?>','<?php echo $r_perm->IDPermisos?>')" title="eliminar este permiso"><img src='images/borrar.gif' border='0'></a></td>					</tr>					<?php }//end WHILE?>				</table>				</td>						</tr>			<?php }//END IF?>			<tr class=bgTop>							<td align=center class=copyright ><b>Buscar &Iacute;tem</b></td>							<td align=center class=copyright><b>Acceso</b></td>						</tr>			<tr class=bgTop>							<td><input type="text" name="SeccionSite_name" id="SeccionSite_name" value="Todos" readonly size="30"><input type=hidden name="IDModuloSite" value=3><input type="hidden" name="IDSeccionSite" id="IDSeccionSite" value="-1" /><input type=button size=10 class=input onclick="popPermItem()" value="..."></td>							<td><select name=Permiso class=input>									<option value=1>acceso denegado</option>									<option value=2>solo lectura</option>									<option value=3>lectura - escritura</option>								</select>				</td>						</tr>			<tr class=bgTop>				<td colspan=2 align="center">					<input type="hidden" name="mod" value="<?php echo $MOD?>"><input type="hidden" name="id_perm" value="-1">					<input type=hidden name=ID value="<?php echo $r->$Key ?>"> 					<input type=hidden name=action value="<?php echo $newmode?>"> 					<input type=submit name=submit value="<?php echo $submit_caption ?>" class=submit>				</td>			</tr>		</table>		</td>	</tr></table>	</form><?php }// End function print_form()?>